def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    bases = set(classes)
    stack = list(bases)
    visited = set()

    while stack:
        cls = stack.pop()
        if cls not in visited:
            visited.add(cls)
            stack.extend(set(cls.__bases__) - visited)

    return list(visited)
