def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption(expr):
        if isinstance(expr, (tuple, list)):
            if len(expr) == 2 and expr[0] in ['&', '|']:
                a, b = expr[1], expr[2]
                if expr[0] == '&':
                    if (isinstance(b, (tuple, list)) and b[0] == '|'):
                        if b[1] == expr[1] or b[2] == a:
                            return expr[1]
                    if (isinstance(b, (tuple, list)) and b[0] == '&'):
                        if b[1] == expr[1]:
                            return b[2]
                        if b[2] == expr[1]:
                            return b[1]
                elif expr[0] == '|':
                    if (isinstance(b, (tuple, list)) and b[0] == '&'):
                        if b[1] == expr[1] or b[2] == a:
                            return expr[1]
                    if (isinstance(b, (tuple, list)) and b[0] == '|'):
                        if b[1] == expr[1]:
                            return b[2]
                        if b[2] == expr[1]:
                            return b[1]
        return expr

    return [apply_absorption(arg) for arg in args]
