def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """

    size = size.replace(" ", "")
    if size[-1] in ['K', 'M', 'G', 'T', 'P']:
        value = float(size[:-1])
        unit = size[-1].upper()
        if unit == 'K': return int(value * 1000)
        elif unit == 'M': return int(value * 1000 ** 2)
        elif unit == 'G': return int(value * 1000 ** 3)
        elif unit == 'T': return int(value * 1000 ** 4)
        elif unit == 'P': return int(value * 1000 ** 5)
    else:
        return int(size)
