import subprocess


def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if isinstance(commands, str):
        commands = [commands]

    if verbose:
        print(f"Running command: {' '.join(commands + args)}")
        if cwd:
            print(f"Working directory: {cwd}")

    result = subprocess.run(commands + args, cwd=cwd, shell=False, capture_output=not hide_stderr, text=True, env=env)

    if verbose:
        if not hide_stderr:
            print("Standard output:")
            print(result.stdout)
        if result.stderr:
            print("Standard error:")
            print(result.stderr)

    if result.returncode != 0:
        raise subprocess.CalledProcessError(result.returncode, commands + args, output=result.stdout, stderr=result.stderr)

    return result.stdout
