def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    def parse_json(json_content):
        data = json.loads(json_content)
        return data

    def parse_xrd(xrd_content):
        root = ET.fromstring(xrd_content)
        data = {}
        for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}link'):
            rel = link.get('{http://www.w3.org/1999/02/22-rdf-syntax-ns#}resource')
            href = link.get('href')
            if rel and href:
                data[rel] = href
        return data

    if document.startswith('{'):
        return parse_json(document)
    elif '<' in document and '</' in document:
        return parse_xrd(document)
    else:
        raise ValueError("Unknown format for Diaspora webfinger document")
