def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    def expand_dict(d):
        if isinstance(d, dict):
            return {k: expand_dict(v) for k, v in d.items()}
        elif isinstance(d, list):
            return [expand_dict(x) for x in d]
        elif isinstance(d, str):
            if d.startswith('@'):  # Check if the string starts with '@'
                # Resolve the include directive
                include_path = d[1:]  # Extract the path after '@'
                with open(include_path, 'r') as file:
                    return expand_dict(json.load(file))
            else:
                return d
        else:
            return d

    self.parser_dict = expand_dict(parser_dict)
