def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    for arg in args:
        min_val = arg.get('min', None)
        max_val = arg.get('max', None)
        value = arg.get('value')

        if min_val is not None and value < min_val:
            raise ValueError(f"The value {value} for {arg.get('name')} is below the minimum allowed value of {min_val}.")

