def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from os.path import join, isfile

    flat_dict = {}

    def flatten_dict(d, parent=None):
        for k, v in d.items():
            new_key = f"{parent}.{k}" if parent else k
            if isinstance(v, dict):
                flatten_dict(v, parent=new_key)
            else:
                flat_dict[new_key] = v

    spec_file = join(plugin_dir, "spec.json")
    if isfile(spec_file):
        with open(spec_file, 'r') as f:
            plugin_spec = json.load(f)
            flatten_dict(plugin_spec)

    return flat_dict
